def f(g):
    g=[list(r) for r in g]; h=len(g); w=len(g[0])
    res=[r[:] for r in g]
    if len(res)%2==0:
        n=w//2
        for i in range(h):
            res[i][n:]=[g[i][n-1-j] for j in range(n)]
    else:
        n=(w-1)//2
        for i in range(h):
            res[i][n+1:]=[g[i][n-1-j] for j in range(n)]
    return [list(map(int,r)) for r in res]

